"""Demonstrate the functional equation of the full Ihara determinant:
(q u^2)^n * prod_j p(l_j, q, 1/(qu)) = prod_j p(l_j, q, u)."""
from __future__ import annotations
from typing import List

def local_factor(lam: complex, q: complex, u: complex) -> complex:
    return 1 - lam * u + q * u ** 2

def det_funeq_residual(spectrum: List[float], q: float, u: complex) -> float:
    n = len(spectrum)
    lhs = (q * u ** 2) ** n
    for lam in spectrum:
        lhs *= local_factor(lam, q, 1 / (q * u))
    rhs = 1 + 0j
    for lam in spectrum:
        rhs *= local_factor(lam, q, u)
    return abs(lhs - rhs)

if __name__ == "__main__":
    spectrum = [3.0, 1.4142, 0.0, -1.4142, -3.0]
    for u in [0.37 + 0.2j, 0.9j, 0.51]:
        print(f"u={u}: residual = {det_funeq_residual(spectrum, 3.0, u):.2e}")
